-- Cloudflare D1 SQLite Schema & Seed Data for IPA (異丙醇) 報價與出貨單船期自動追蹤系統

CREATE TABLE IF NOT EXISTS fx_rates (
    record_date TEXT PRIMARY KEY,
    usd_twd REAL,
    usd_cny REAL,
    cny_twd REAL,
    updated_at TEXT
);

CREATE TABLE IF NOT EXISTS chemical_quotes (
    record_date TEXT,
    chem_key TEXT,
    chem_name TEXT,
    category TEXT,
    raw_price REAL,
    raw_unit TEXT,
    usd_mt REAL,
    twd_kg REAL,
    usd_twd_rate REAL,
    note TEXT,
    updated_at TEXT,
    PRIMARY KEY (record_date, chem_key)
);

CREATE TABLE IF NOT EXISTS shipment_tracking (
    id INTEGER PRIMARY KEY AUTOINCREMENT,
    order_no TEXT,
    container_no TEXT UNIQUE,
    prefix TEXT,
    carrier TEXT,
    box_type TEXT,
    vessel_name TEXT,
    voyage TEXT,
    chem_item TEXT,
    qty_mt REAL,
    buy_price_usd_mt REAL,
    buy_price_twd_kg REAL,
    pol TEXT,
    pod TEXT,
    etd TEXT,
    eta TEXT,
    status TEXT,
    ais_url TEXT,
    carrier_url TEXT,
    twport_url TEXT,
    note TEXT,
    updated_at TEXT
);

